'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var EPS = require( '@stdlib/constants/float64/eps' );
var pkg = require( './../package.json' ).name;
var gammainc = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'float64'
};


// MAIN //

bench( pkg, function benchmark( b ) {
	var x;
	var y;
	var z;
	var i;

	x = uniform( b.iterations, 10, 1000, options );
	y = uniform( b.iterations, EPS, 1000, options );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		z = gammainc( x[ i ], y[ i ] );
		if ( isnan( z ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( z ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':regularized=true', function benchmark( b ) {
	var x;
	var y;
	var z;
	var i;

	x = uniform( b.iterations, 0, 1000, options );
	y = uniform( b.iterations, EPS, 1000, options );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		z = gammainc( x[ i ], y[ i ], true );
		if ( isnan( z ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( z ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

